    "LINE [[STEP](x1, y1)]-[STEP](x2, y2) [, color [, B[F] [, style]]]   (or LINE INPUT [#file,] [prompt;] variable$)\0"
    "DIM\0"
    "DIM [SHARED] name[(bounds)] [AS type] [, name ...]\0"
    "REDIM\0"
    "REDIM [SHARED] name(bounds) [AS type] [, name ...]\0"
    "CONST\0"
    "CONST name = constant-expression [, name = constant-expression] ...\0"
    "FOR\0"
    "FOR counter = start TO end [STEP step]\0"
    "NEXT\0"
    "NEXT [counter [, counter] ...]\0"
    "IF\0"
    "IF condition THEN statements [ELSE statements]   (or a block: IF condition THEN, then END IF)\0"
    "WHILE\0"
    "WHILE condition\0"
    "DO\0"
    "DO [WHILE | UNTIL condition]\0"
    "LOOP\0"
    "LOOP [WHILE | UNTIL condition]\0"
    "SELECT\0"
    "SELECT CASE expression\0"
    "CASE\0"
    "CASE value [, value ...] | CASE a TO b | CASE IS operator value | CASE ELSE\0"
    "GOTO\0"
    "GOTO label\0"
    "GOSUB\0"
    "GOSUB label\0"
    "ON\0"
    "ON expression GOTO | GOSUB label [, label] ...   (or ON ERROR GOTO label, ON TIMER(n) GOSUB label)\0"
    "OPEN\0"
    "OPEN file$ [FOR mode] [ACCESS access] [lock] AS #number [LEN = record-length]\0"
    "CLOSE\0"
    "CLOSE [[#]number [, [#]number] ...]\0"
    "READ\0"
    "READ variable [, variable] ...\0"
    "DATA\0"
    "DATA constant [, constant] ...\0"
    "SUB\0"
    "SUB name [(parameters)] [STATIC]\0"
    "FUNCTION\0"
    "FUNCTION name [(parameters)] [STATIC]\0"
    "DECLARE\0"
    "DECLARE SUB | FUNCTION name [(parameters)]\0"
    "CALL\0"
    "CALL name [(arguments)]\0"
    "TYPE\0"
    "TYPE name, then field AS type lines, then END TYPE\0"
    "DEF\0"
    "DEF FNname[(parameters)] = expression   (or DEF SEG [= segment])\0"
    "COLOR\0"
    "COLOR [foreground] [, [background] [, border]]\0"
    "LOCATE\0"
    "LOCATE [row] [, [column] [, [cursor] [, start [, stop]]]]\0"
    "SCREEN\0"
    "SCREEN [mode] [, [colorswitch] [, [activepage] [, visiblepage]]]\0"
    "PUT\0"
    "PUT [#]file [, record] [, variable]   (graphics: PUT (x, y), array [, action])\0"
    "GET\0"
    "GET [#]file [, record] [, variable]   (graphics: GET (x1, y1)-(x2, y2), array)\0"
    "SWAP\0"
    "SWAP variable1, variable2\0"
    "RANDOMIZE\0"
    "RANDOMIZE [seed]\0"
    "SHARED\0"
    "SHARED variable [, variable] ...\0"
    "COMMON\0"
    "COMMON [SHARED] [/block/] variable [, variable] ...\0"
    "EXIT\0"
    "EXIT FOR | DO | SUB | FUNCTION | DEF\0"
    "END\0"
    "END [IF | SELECT | SUB | FUNCTION | DEF | TYPE]\0"
    "WRITE\0"
    "WRITE [#file,] [expression [, expression] ...]\0"
    "LOOP\0"
    "LOOP [WHILE | UNTIL condition]\0"
    "SELECT\0"
    "SELECT CASE expression\0"
    "ERASE\0"
    "ERASE array [, array] ...\0"
    "OPTION\0"
    "OPTION BASE 0 | 1\0"
    "";
